/* ═══════════════════════════════════════════
   TERMINAL CLI THEME – Complete Styling
   ═══════════════════════════════════════════ */

/* ── Global Terminal Reset ── */
:root[data-theme="terminal-cli"],
:root[data-theme="terminal-cli"] * {
  font-family: 'IBM Plex Mono', 'JetBrains Mono', 'Courier New', monospace !important;
  border-radius: 0 !important;
  text-shadow: none !important;
}

:root[data-theme="terminal-cli"] body {
  background: #0a0a0a;
  color: #50fa7b;
  -webkit-font-smoothing: none;
  -moz-osx-font-smoothing: unset;
}

/* ── Typography ── */
:root[data-theme="terminal-cli"] h1,
:root[data-theme="terminal-cli"] h2,
:root[data-theme="terminal-cli"] h3 {
  font-family: 'IBM Plex Mono', monospace !important;
  text-transform: none;
  letter-spacing: 0;
  color: #50fa7b;
  font-weight: 700;
}

:root[data-theme="terminal-cli"] h1::before { content: '# '; color: #6272a4; }
:root[data-theme="terminal-cli"] h2::before { content: '## '; color: #6272a4; }
:root[data-theme="terminal-cli"] h3::before { content: '### '; color: #6272a4; }

/* ── Terminal Cards ── */
:root[data-theme="terminal-cli"] .glass-card {
  border: 1px solid #333 !important;
  background: #0d0d0d !important;
  box-shadow: none !important;
  position: relative;
  font-size: 0.85em;
  line-height: 1.5;
}

:root[data-theme="terminal-cli"] .glass-card::before {
  content: '┌─ ' attr(data-widget-type) ' ──────────────────────────────┐';
  display: block;
  color: #50fa7b;
  font-size: 0.7em;
  padding: 2px 4px;
  white-space: pre;
  overflow: hidden;
}

:root[data-theme="terminal-cli"] .glass-card::after {
  content: '└──────────────────────────────────────────────┘';
  display: block;
  color: #50fa7b;
  font-size: 0.7em;
  padding: 0 4px 4px;
}

:root[data-theme="terminal-cli"] .glass-card:hover {
  border-color: #50fa7b !important;
}

/* ── Header ── */
:root[data-theme="terminal-cli"] .glass-header {
  background: #111 !important;
  border-bottom: 1px solid #333 !important;
  backdrop-filter: none !important;
  height: 28px;
  font-size: 0.75em;
}

:root[data-theme="terminal-cli"] .glass-header::before {
  content: '┌─[iora@home]─[terminal]──────────────────────────────────────────────────────────────────────┐';
  display: block;
  color: #50fa7b;
  font-size: 0.65em;
  padding: 0 4px;
  white-space: nowrap;
  overflow: hidden;
}

/* ── Navigation ── */
:root[data-theme="terminal-cli"] [data-nav="root"] {
  background: #0d0d0d !important;
  border-top: 1px solid #333 !important;
  font-family: 'IBM Plex Mono', monospace !important;
  font-size: 0.65em;
}

:root[data-theme="terminal-cli"] [data-nav="root"] button {
  font-family: 'IBM Plex Mono', monospace !important;
  text-transform: none;
  letter-spacing: 0;
  min-height: 24px !important;
  padding: 2px 8px !important;
  font-size: 0.9em !important;
  border: 1px solid #333;
  background: #0d0d0d;
  color: #6272a4;
}

:root[data-theme="terminal-cli"] [data-nav="root"] button[data-active="true"] {
  color: #50fa7b !important;
  border-color: #50fa7b !important;
  background: rgba(80,250,123,0.05) !important;
}

:root[data-theme="terminal-cli"] [data-nav="root"] button:hover {
  color: #f8f8f2 !important;
  border-color: #6272a4 !important;
}

/* ── Buttons ── */
:root[data-theme="terminal-cli"] button:not([data-nav] button) {
  font-family: 'IBM Plex Mono', monospace;
  border: 1px solid #333;
  background: #0d0d0d;
  color: #50fa7b;
  text-transform: none;
  letter-spacing: 0;
  padding: 4px 12px;
  font-size: 0.8em;
}

:root[data-theme="terminal-cli"] button:hover:not([data-nav] button) {
  border-color: #50fa7b;
  background: rgba(80,250,123,0.05);
}

/* ── Inputs ── */
:root[data-theme="terminal-cli"] input,
:root[data-theme="terminal-cli"] textarea,
:root[data-theme="terminal-cli"] select {
  font-family: 'IBM Plex Mono', monospace !important;
  background: #0d0d0d !important;
  border: 1px solid #333 !important;
  color: #50fa7b !important;
  caret-color: #50fa7b;
}

:root[data-theme="terminal-cli"] input::placeholder {
  color: #333;
}

:root[data-theme="terminal-cli"] input:focus,
:root[data-theme="terminal-cli"] textarea:focus {
  border-color: #50fa7b !important;
  outline: none !important;
}

/* ── Cursor ── */
:root[data-theme="terminal-cli"] input:focus,
:root[data-theme="terminal-cli"] textarea:focus {
  caret-color: #50fa7b;
  animation: terminal-cursor-blink 1s step-end infinite;
}

@keyframes terminal-cursor-blink {
  0%, 100% { caret-color: #50fa7b; }
  50% { caret-color: transparent; }
}

/* ── Scrollbar ── */
:root[data-theme="terminal-cli"] ::-webkit-scrollbar {
  width: 4px;
  height: 4px;
}

:root[data-theme="terminal-cli"] ::-webkit-scrollbar-track {
  background: #0d0d0d;
}

:root[data-theme="terminal-cli"] ::-webkit-scrollbar-thumb {
  background: #333;
}

:root[data-theme="terminal-cli"] ::-webkit-scrollbar-thumb:hover {
  background: #50fa7b;
}

/* ── Selection ── */
:root[data-theme="terminal-cli"] ::selection {
  background: #50fa7b;
  color: #0a0a0a;
}

/* ── Modals ── */
:root[data-theme="terminal-cli"] [role="dialog"] {
  border: 1px solid #50fa7b !important;
  background: #0d0d0d !important;
  box-shadow: 0 0 30px rgba(80,250,123,0.1) !important;
}

/* ── Notifications ── */
:root[data-theme="terminal-cli"] .sonner-toast {
  font-family: 'IBM Plex Mono', monospace !important;
  border: 1px solid #333 !important;
  background: #0d0d0d !important;
  border-radius: 0 !important;
  font-size: 0.75em;
}

/* ── Progress bars ── */
:root[data-theme="terminal-cli"] [role="progressbar"] {
  background: #0d0d0d !important;
  border: 1px solid #333 !important;
  height: 12px !important;
}

:root[data-theme="terminal-cli"] [role="progressbar"] > div {
  background: #50fa7b !important;
}

/* ── Toggle/Switch ── */
:root[data-theme="terminal-cli"] [role="switch"] {
  border: 1px solid #333 !important;
}

:root[data-theme="terminal-cli"] [role="switch"][data-state="checked"] {
  background: #50fa7b !important;
  border-color: #50fa7b !important;
}

/* ── Badge/Pill ── */
:root[data-theme="terminal-cli"] .badge,
:root[data-theme="terminal-cli"] .pill {
  font-family: 'IBM Plex Mono', monospace;
  border: 1px solid #333;
  background: #0d0d0d;
  color: #50fa7b;
  font-size: 0.65em;
  padding: 1px 6px;
}

/* ── Tooltip ── */
:root[data-theme="terminal-cli"] [role="tooltip"] {
  font-family: 'IBM Plex Mono', monospace;
  background: #0d0d0d;
  border: 1px solid #50fa7b;
  font-size: 0.7em;
  padding: 4px 8px;
}

/* ── Tables ── */
:root[data-theme="terminal-cli"] table {
  border-collapse: collapse;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 0.8em;
}

:root[data-theme="terminal-cli"] th,
:root[data-theme="terminal-cli"] td {
  border: 1px solid #333;
  padding: 4px 8px;
  text-align: left;
}

:root[data-theme="terminal-cli"] th {
  background: #111;
  color: #50fa7b;
  font-weight: 700;
}

/* ── Code blocks ── */
:root[data-theme="terminal-cli"] pre,
:root[data-theme="terminal-cli"] code {
  background: #0d0d0d;
  border: 1px solid #333;
  padding: 8px;
  color: #f8f8f2;
  font-size: 0.8em;
}

/* ── Dialog/Modal title ── */
:root[data-theme="terminal-cli"] [role="dialog"] h2::before {
  content: '┌─ ';
  color: #50fa7b;
}

:root[data-theme="terminal-cli"] [role="dialog"] h2::after {
  content: ' ─┐';
  color: #50fa7b;
}

/* ── Skeleton loading ── */
:root[data-theme="terminal-cli"] .skeleton {
  background: repeating-linear-gradient(90deg, #0d0d0d 0px, #111 20px, #0d0d0d 40px);
  animation: terminal-scan 2s linear infinite;
}

@keyframes terminal-scan {
  0% { background-position: 0 0; }
  100% { background-position: 40px 0; }
}

/* ── Terminal prompt decoration ── */
.terminal-prompt::before {
  content: 'iora@home:~$ ';
  color: #50fa7b;
  font-weight: 700;
}

/* ── ASCII borders for containers ── */
.terminal-box {
  border: 1px solid #333;
  padding: 8px;
  position: relative;
}

.terminal-box::before {
  content: '┌──────────────────────────────┐';
  display: block;
  color: #6272a4;
  font-size: 0.6em;
  line-height: 1;
}

.terminal-box::after {
  content: '└──────────────────────────────┘';
  display: block;
  color: #6272a4;
  font-size: 0.6em;
  line-height: 1;
}

/* ═══════════════════════════════════════════
   KEYBOARD NAVIGATION — Full Keyboard Support
   ═══════════════════════════════════════════ */

/* Focus-visible ring for ALL interactive elements */
:root[data-theme="terminal-cli"] *:focus-visible {
  outline: 1px solid #50fa7b !important;
  outline-offset: 1px !important;
  box-shadow: 0 0 6px rgba(80,250,123,0.3) !important;
}

/* Skip-to-content for keyboard users */
:root[data-theme="terminal-cli"] .skip-link {
  position: absolute;
  top: -100px;
  left: 4px;
  background: #0d0d0d;
  color: #50fa7b;
  border: 1px solid #50fa7b;
  padding: 4px 8px;
  font-family: 'IBM Plex Mono', monospace;
  font-size: 0.75em;
  z-index: 10000;
}
:root[data-theme="terminal-cli"] .skip-link:focus {
  top: 4px;
}

/* Tab-navigable cards */
:root[data-theme="terminal-cli"] .glass-card:focus-visible {
  border-color: #50fa7b !important;
  box-shadow: 0 0 12px rgba(80,250,123,0.2) !important;
}

/* Keyboard-active nav buttons */
:root[data-theme="terminal-cli"] [data-nav="root"] button:focus-visible {
  outline: 1px solid #50fa7b !important;
  outline-offset: -2px !important;
  color: #50fa7b !important;
  border-color: #50fa7b !important;
}

/* Focus indicator for links */
:root[data-theme="terminal-cli"] a:focus-visible {
  outline: 1px solid #50fa7b !important;
  outline-offset: 2px !important;
  text-decoration: underline !important;
}

/* Dropdown/select keyboard */
:root[data-theme="terminal-cli"] select:focus-visible {
  border-color: #50fa7b !important;
  box-shadow: 0 0 8px rgba(80,250,123,0.2) !important;
}

/* Range/slider keyboard focus */
:root[data-theme="terminal-cli"] input[type="range"]:focus-visible {
  outline: 1px solid #50fa7b !important;
}
:root[data-theme="terminal-cli"] input[type="range"]:focus-visible::-webkit-slider-thumb {
  box-shadow: 0 0 6px rgba(80,250,123,0.4);
}

/* Checkbox/radio keyboard focus */
:root[data-theme="terminal-cli"] input[type="checkbox"]:focus-visible + label,
:root[data-theme="terminal-cli"] input[type="radio"]:focus-visible + label {
  outline: 1px solid #50fa7b;
  outline-offset: 2px;
}

/* Keyboard shortcut hints */
:root[data-theme="terminal-cli"] [aria-label]::after {
  font-size: 0.6em;
  color: #6272a4;
}

/* Reduced motion for vestibular disorders */
@media (prefers-reduced-motion: reduce) {
  :root[data-theme="terminal-cli"] * {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
  :root[data-theme="terminal-cli"] .terminal-scanlines-overlay {
    display: none !important;
  }
}


/* ═══════════════════════════════════════════
   CRT RETRO MONITOR EFFECT
   Röhrenmonitor-Simulation mit Scanlines,
   Phosphor-Glow, Curvature, Chroma-Aberration
   ═══════════════════════════════════════════ */

/* ── CRT Container ── */
:root[data-theme="terminal-cli"] body {
  position: relative;
  overflow: hidden;
}

/* ── CRT Power-On Animation ── */
:root[data-theme="terminal-cli"].crt-booting body::before {
  content: '';
  position: fixed;
  inset: 0;
  background: #0a0a0a;
  z-index: 99999;
  animation: crt-power-on 0.8s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  transform-origin: center;
}

/* ── CRT Scanlines Overlay ── */
:root[data-theme="terminal-cli"] body::after {
  content: '';
  position: fixed;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    rgba(0,0,0,0) 0px,
    rgba(0,0,0,0) 2px,
    rgba(0,0,0,0.08) 2px,
    rgba(0,0,0,0.08) 4px
  );
  pointer-events: none;
  z-index: 9998;
  animation: crt-scanline-move 8s linear infinite;
}

/* ── CRT Scanlines 2: feinere horizontale Linien ── */
:root[data-theme="terminal-cli"] .crt-scanlines-fine {
  position: fixed;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 1px,
    rgba(0,0,0,0.05) 1px,
    rgba(0,0,0,0.05) 2px
  );
  pointer-events: none;
  z-index: 9997;
}

/* ── CRT Vignette (abdunkelnde Ränder) ── */
:root[data-theme="terminal-cli"] .crt-vignette {
  position: fixed;
  inset: 0;
  background: radial-gradient(
    ellipse at center,
    transparent 50%,
    rgba(0,0,0,0.3) 85%,
    rgba(0,0,0,0.6) 100%
  );
  pointer-events: none;
  z-index: 9996;
}

/* ── CRT Phosphor Glow ── */
:root[data-theme="terminal-cli"] .crt-glow {
  position: fixed;
  inset: 0;
  background: radial-gradient(
    ellipse at center,
    rgba(80,250,123,0.04) 0%,
    rgba(80,250,123,0.02) 40%,
    transparent 70%
  );
  pointer-events: none;
  z-index: 9995;
  animation: crt-phosphor-decay 0.05s ease-in-out infinite;
}

/* ── CRT Screen Curvature (Bildröhren-Wölbung) ── */
:root[data-theme="terminal-cli"].crt-curved {
  border-radius: 18px / 12px !important;
  overflow: hidden;
  box-shadow: 
    inset 0 0 60px rgba(0,0,0,0.4),
    inset 0 0 120px rgba(0,0,0,0.2),
    0 0 30px rgba(80,250,123,0.08);
}

:root[data-theme="terminal-cli"] .crt-curvature-mask {
  position: fixed;
  inset: -5%;
  background: radial-gradient(
    ellipse at center,
    transparent 55%,
    rgba(0,0,0,0.05) 75%,
    rgba(0,0,0,0.15) 90%,
    rgba(0,0,0,0.3) 100%
  );
  pointer-events: none;
  z-index: 9994;
  border-radius: 50% / 30%;
}

/* ── CRT Screen Flicker ── */
@keyframes crt-flicker-global {
  0%   { opacity: 1; }
  3%   { opacity: 0.97; }
  6%   { opacity: 1; }
  50%  { opacity: 1; }
  53%  { opacity: 0.98; }
  54%  { opacity: 1; }
  95%  { opacity: 1; }
  96%  { opacity: 0.96; }
  97%  { opacity: 1; }
  100% { opacity: 1; }
}

:root[data-theme="terminal-cli"].crt-flickering {
  animation: crt-flicker-global 0.15s infinite;
}

:root[data-theme="terminal-cli"].crt-flickering * {
  animation: crt-flicker-global 0.2s infinite !important;
}

/* ── CRT Noise/Interference Overlay ── */
:root[data-theme="terminal-cli"] .crt-noise {
  position: fixed;
  inset: -50%;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.04'/%3E%3C/svg%3E");
  background-size: 128px 128px;
  pointer-events: none;
  z-index: 9993;
  opacity: 0.3;
  animation: crt-noise 0.5s steps(5) infinite;
}

/* ── CRT Chromatic Aberration (RGB-Shift an Rändern) ── */
:root[data-theme="terminal-cli"] .crt-chroma {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9992;
  background: 
    radial-gradient(ellipse at 0% 0%, rgba(255,0,0,0.03) 0%, transparent 40%),
    radial-gradient(ellipse at 100% 0%, rgba(0,0,255,0.03) 0%, transparent 40%),
    radial-gradient(ellipse at 0% 100%, rgba(0,0,255,0.02) 0%, transparent 40%),
    radial-gradient(ellipse at 100% 100%, rgba(255,0,0,0.02) 0%, transparent 40%);
}

/* ── CRT Text-Shadow Glow ── */
:root[data-theme="terminal-cli"].crt-text-glow h1,
:root[data-theme="terminal-cli"].crt-text-glow h2,
:root[data-theme="terminal-cli"].crt-text-glow h3,
:root[data-theme="terminal-cli"].crt-text-glow p,
:root[data-theme="terminal-cli"].crt-text-glow span,
:root[data-theme="terminal-cli"].crt-text-glow .glass-card {
  text-shadow: 0 0 4px rgba(80,250,123,0.3), 0 0 8px rgba(80,250,123,0.1);
}

/* ── CRT Phosphor Persistence (Nachleuchten) ── */
:root[data-theme="terminal-cli"] .crt-phosphor-trail * {
  transition: color 0.1s ease-out, background-color 0.15s ease-out !important;
}

/* ── Glass Screen Reflection ── */
:root[data-theme="terminal-cli"] .crt-glass-reflection {
  position: fixed;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(255,255,255,0.03) 0%,
    transparent 30%,
    transparent 70%,
    rgba(255,255,255,0.01) 100%
  );
  pointer-events: none;
  z-index: 9991;
}

/* ── CRT Subpixel Rendering Simulation ── */
:root[data-theme="terminal-cli"].crt-subpixel .glass-card {
  image-rendering: pixelated;
  -webkit-font-smoothing: none;
  -moz-osx-font-smoothing: unset;
}

/* ── Horizontal distortion lines (wie bei alten Monitoren) ── */
@keyframes crt-distortion-line {
  0%   { top: -5%; opacity: 0; }
  5%   { top: 15%; opacity: 0.15; }
  10%  { top: 15%; opacity: 0; }
  40%  { top: 55%; opacity: 0; }
  45%  { top: 55%; opacity: 0.1; }
  50%  { top: 55%; opacity: 0; }
  80%  { top: 85%; opacity: 0; }
  85%  { top: 85%; opacity: 0.12; }
  90%  { top: 85%; opacity: 0; }
  100% { top: -5%; opacity: 0; }
}

:root[data-theme="terminal-cli"] .crt-distortion {
  position: fixed;
  left: 0;
  right: 0;
  height: 3px;
  background: rgba(80,250,123,0.1);
  pointer-events: none;
  z-index: 9990;
  animation: crt-distortion-line 8s linear infinite;
}

/* ── CRT Overscan Borders ── */
:root[data-theme="terminal-cli"].crt-overscan body {
  padding: 12px !important;
  background: #050505 !important;
}

:root[data-theme="terminal-cli"] .crt-overscan-border {
  position: fixed;
  inset: 8px;
  border: 2px solid rgba(80,250,123,0.04);
  pointer-events: none;
  z-index: 9989;
  border-radius: 12px;
}
